  WHERE id = p_auth_user_id
  LIMIT 1;
END;
$$;

-- 6. Narrow SECURITY DEFINER Helper: Lookup Profile by Email (Auth Discovery)
CREATE OR REPLACE FUNCTION public.lookup_profile_by_email(p_email TEXT)
